DimensionLine:
import type React from 'react';
import type { Point } from '@/types/geometry';
import { Text, ArrowMarker } from '@enji-drawings-core';

interface DimensionLineProps {
  start: Point;
  end: Point;
  label: string;
  switchPosition?: boolean;
  showMidpoint?: boolean;
  perpendicularOffset?: number;
}

const DimensionLine: React.FC<DimensionLineProps> = ({
  start,
  end,
  label,
  switchPosition = false,
  perpendicularOffset = 10, // Default 5px perpendicular offset
}) => {
  const ARROW_OFFSET = 3; // moves the arrow by the size of the arrow

  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const angle = Math.atan2(dy, dx);
  const perpendicularAngle = angle + Math.PI / 2; // 90 degrees perpendicular to line

  // Apply perpendicular offset to start and end points
  const offsetDirection = switchPosition ? 1 : -1;
  const offsetStart = {
    x: start.x + offsetDirection * perpendicularOffset * Math.cos(perpendicularAngle),
    y: start.y + offsetDirection * perpendicularOffset * Math.sin(perpendicularAngle),
  };

  const offsetEnd = {
    x: end.x + offsetDirection * perpendicularOffset * Math.cos(perpendicularAngle),
    y: end.y + offsetDirection * perpendicularOffset * Math.sin(perpendicularAngle),
  };

  const dimLineStart = {
    x: offsetStart.x + ARROW_OFFSET * Math.cos(angle),
    y: offsetStart.y + ARROW_OFFSET * Math.sin(angle),
  };

  const dimLineEnd = {
    x: offsetEnd.x - ARROW_OFFSET * Math.cos(angle),
    y: offsetEnd.y - ARROW_OFFSET * Math.sin(angle),
  };

  const midPoint = {
    x: (dimLineStart.x + dimLineEnd.x) / 2,
    y: (dimLineStart.y + dimLineEnd.y) / 2,
  };

  // Calculate perpendicular offset for text placement
  const TEXT_OFFSET = 7; // pixels to offset text from the line

  const textRotation = (angle * 180) / Math.PI;

  const textPosition = {
    x: midPoint.x + offsetDirection * TEXT_OFFSET * Math.cos(perpendicularAngle),
    y: midPoint.y + offsetDirection * TEXT_OFFSET * Math.sin(perpendicularAngle),
  };

  const shouldFlipText = textRotation > 90 || textRotation < -90;
  const finalRotation = shouldFlipText ? textRotation + 180 : textRotation;

  return (
    <g>
      <ArrowMarker id="dimension-arrow" />
      {/* Thin extension lines connecting original points to dimension line */}
      <line stroke="gray" strokeWidth="0.5" x1={start.x} y1={start.y} x2={offsetStart.x} y2={offsetStart.y} />
      <line stroke="gray" strokeWidth="0.5" x1={end.x} y1={end.y} x2={offsetEnd.x} y2={offsetEnd.y} />
      {/* Main dimension line with arrows */}
      <line
        markerEnd="url(#dimension-arrow-end)"
        markerStart="url(#dimension-arrow-start)"
        stroke="black"
        strokeWidth="1"
        x1={dimLineStart.x}
        x2={dimLineEnd.x}
        y1={dimLineStart.y}
        y2={dimLineEnd.y}
      />
      <Text
        position={textPosition}
        textAnchor="middle"
        transform={`rotate(${finalRotation} ${textPosition.x} ${textPosition.y})`}
      >
        {label}
      </Text>
    </g>
  );
};

export default DimensionLine;

DoubleBendBar:
import type React from 'react';
import type { Point } from '@/types/geometry';
import RadiusAnnotation from './RadiusAnnotation';
import DimensionLine from './DimensionLine';
import {
  getInitialBarPoints,
  getNextArcLinePoints,
  getInitialBarPath,
  getFinalBendPath,
} from './mathematics-points-bending';

interface DoubleBendBarProps {
  position: Point;
  barThickness: number;
  lengthA: number;
  lengthB: number;
  lengthC: number;
  angle1: number;
  angle2: number;
  firstInnerRadius: number;
  secondInnerRadius: number;
  switchFirstBend?: boolean;
  switchSecondBend?: boolean;
  color?: string;
  rotation?: number;
  showRadius?: boolean;
  showDimensions?: boolean;
}

const DoubleBendBar: React.FC<DoubleBendBarProps> = ({
  position,
  barThickness,
  lengthA,
  lengthB,
  lengthC,
  angle1,
  angle2,
  firstInnerRadius,
  secondInnerRadius,
  switchFirstBend = false,
  switchSecondBend = false,
  color = '#000',
  rotation = 0,
  showRadius = false,
  showDimensions = false,
}) => {
  if (angle1 < 0 || angle1 > 180 || angle2 < 0 || angle2 > 180) {
    throw new Error('Angles must be between 0 and 180 degrees');
  }

  if (rotation < 0 || rotation > 90) {
    throw new Error('Rotation must be between 0 and 90 degrees');
  }

  const angle1Rad = (angle1 * Math.PI) / 180;
  const angle2Rad = (angle2 * Math.PI) / 180;
  const firstOffset = firstInnerRadius + barThickness;

  const firstBarAngleRad = (rotation * Math.PI) / 180;

  const { firstBar, circleCenterFirst, circleStartFirst } = getInitialBarPoints(
    position,
    switchFirstBend,
    lengthA,
    firstInnerRadius,
    barThickness,
    firstBarAngleRad
  );

  const secondOffset = secondInnerRadius + barThickness;

  const {
    nextBar: secondBar,
    nextCircleCenter: circleCenterSecond,
    nextCircleStart: circleStartSecond,
  } = getNextArcLinePoints(
    firstBar,
    switchFirstBend,
    switchSecondBend,
    firstInnerRadius,
    secondInnerRadius,
    lengthB,
    barThickness,
    angle1Rad,
    circleStartFirst,
    circleCenterFirst
  );

  const { nextBar: thirdBar } = getNextArcLinePoints(
    secondBar,
    switchSecondBend,
    false, // no next bend
    secondInnerRadius,
    0, // no next radius
    lengthC,
    barThickness,
    angle2Rad,
    circleStartSecond,
    circleCenterSecond
  );

  return (
    <>
      {/* First Path - First Bar and Connection to Second Bar */}
      <path
        d={getInitialBarPath(firstBar, secondBar, switchFirstBend, firstInnerRadius, firstOffset)}
        fill="white"
        stroke={color}
        strokeWidth={1}
      />

      {/* Second Path - Final Bend Plus C Bar */}
      <path
        d={getFinalBendPath(secondBar, thirdBar, switchSecondBend, secondInnerRadius, secondOffset)}
        fill="white"
        stroke={color}
        strokeWidth={1}
        fillRule="nonzero"
      />

      {showRadius && (
        <>
          <RadiusAnnotation center={circleCenterFirst} radius={firstInnerRadius} color={color} />
          <RadiusAnnotation center={circleCenterSecond} radius={secondInnerRadius} color={color} />
        </>
      )}
      {showDimensions && (
        <>
          {/* Length A dimension */}
          <DimensionLine
            switchPosition
            start={{ x: firstBar.start.x, y: firstBar.start.y }}
            end={{ x: firstBar.end.x, y: firstBar.end.y }}
            label={`A=${lengthA}`}
          />

          {/* Length B dimension */}
          <DimensionLine
            start={{ x: secondBar.startOffset.x, y: secondBar.startOffset.y }}
            end={{ x: secondBar.endOffset.x, y: secondBar.endOffset.y }}
            label={`B=${lengthB}`}
          />

          {/* Length C dimension */}
          <DimensionLine
            switchPosition
            start={{ x: thirdBar.startOffset.x, y: thirdBar.startOffset.y }}
            end={{ x: thirdBar.endOffset.x, y: thirdBar.endOffset.y }}
            label={`C=${lengthC}`}
          />
        </>
      )}
    </>
  );
};

export default DoubleBendBar;

DrawingCanvas:
'use client';

import type React from 'react';
import { useState } from 'react';
import { ServerDrawingGrid, ServerDrawingControls } from './server-drawing-canvas';
import type { Point } from '@/types/geometry';

interface DrawingCanvasProps {
  width?: number;
  height: number;
  gridSize?: number;
  labelInterval?: number;
  strokeColor?: string;
  strokeWidth?: number;
  labelColor?: string;
  labelFontSize?: number;
  className?: string;
  startPoint?: Point;
  children?: React.ReactNode;
}

const DrawingCanvas: React.FC<DrawingCanvasProps> = ({
  width = 800, // pay attenation to parent container width
  height,
  gridSize = 10,
  labelInterval = 50,
  strokeColor = '#ddd',
  strokeWidth = 0.5,
  labelColor = '#999',
  labelFontSize = 8,
  className,
  startPoint = { x: 0, y: 0 },
  children,
}) => {
  const [zoom, setZoom] = useState(1);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [initialClickPos, setInitialClickPos] = useState({ x: 0, y: 0 });

  const minZoom = 0.3;
  const maxZoom = 2;
  const zoomStep = 0.25;

  const handleZoomIn = () => {
    setZoom((prevZoom) => Math.min(prevZoom + zoomStep, maxZoom));
  };

  const handleZoomOut = () => {
    setZoom((prevZoom) => Math.max(prevZoom - zoomStep, minZoom));
  };

  const handleMouseDown = (e: React.MouseEvent<SVGSVGElement>) => {
    setIsDragging(true);
    setInitialClickPos({
      x: e.clientX - dragOffset.x,
      y: e.clientY - dragOffset.y,
    });
  };

  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!isDragging) return;
    setDragOffset({
      x: e.clientX - initialClickPos.x,
      y: e.clientY - initialClickPos.y,
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const handleRecenter = () => {
    setZoom(1);
    setDragOffset({ x: 0, y: 0 });
  };

  // Calculate the scaled dimensions for the viewBox
  const viewBoxWidth = width / zoom;
  const viewBoxHeight = height / zoom;
  const viewBox = {
    x: -dragOffset.x / zoom,
    y: -dragOffset.y / zoom,
  };

  // Calculate grid boundaries based on viewBox
  const gridStart = {
    x: Math.floor(viewBox.x / gridSize) * gridSize,
    y: Math.floor(viewBox.y / gridSize) * gridSize,
  };
  const gridEnd = {
    x: Math.ceil((viewBox.x + viewBoxWidth) / gridSize) * gridSize,
    y: Math.ceil((viewBox.y + viewBoxHeight) / gridSize) * gridSize,
  };

  return (
    <div className="relative">
      <svg
        width={width}
        height={height}
        viewBox={`${viewBox.x} ${viewBox.y} ${viewBoxWidth} ${viewBoxHeight}`}
        className={`${className} ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        aria-label="Drawing canvas"
      >
        <title>Drawing canvas</title>
        <g>
          <ServerDrawingGrid
            gridStart={gridStart}
            gridEnd={gridEnd}
            gridSize={gridSize}
            labelInterval={labelInterval}
            strokeColor={strokeColor}
            strokeWidth={strokeWidth}
            labelColor={labelColor}
            labelFontSize={labelFontSize}
            viewBox={viewBox}
            zoom={zoom}
            startPoint={startPoint}
          />
          {children}
        </g>
      </svg>
      <ServerDrawingControls
        zoom={zoom}
        minZoom={minZoom}
        maxZoom={maxZoom}
        onZoomIn={handleZoomIn}
        onZoomOut={handleZoomOut}
        onRecenter={handleRecenter}
      />
    </div>
  );
};

export default DrawingCanvas;

